17	atb::Operation* Linear(const LlamaMlpParamGb &param)
18	{
19	    atb::Operation* op = nullptr;
20	    atb::infer::LinearParam linearParam;
21	    linearParam.hasBias = false;
22	    linearParam.transposeB = param.transpose;
23	    CreateOperation(linearParam, &op);
