35	atb::Operation* Swish(const LlamaMlpParamGb &param)
36	{
37	    atb::Operation* op = nullptr;
38	    atb::infer::ActivationParam activationParam;
39	    activationParam.activationType = atb::infer::ActivationType::ACTIVATION_SWISH;
40	    CreateOperation(activationParam, &op);
41	    return op;
42	}
