44	atb::Operation* Mul(const LlamaMlpParamGb &param)
45	{
46	    atb::Operation* op = nullptr;
47	    atb::infer::ElewiseParam elewiseParam;
48	    elewiseParam.elewiseType = atb::infer::ElewiseParam::ElewiseType::ELEWISE_MUL;
49	    CreateOperation(elewiseParam, &op);
50	    return op;
51	}
