53	atb::Status CreateLlamaMlpOperationByGraphOpBuilder(const LlamaMlpParamGb &param, atb::Operation **operation)
54	{
55	    atb::InferShapeFunc inferShapeFunc = [=](const atb::SVector<atb::TensorDesc> &inTensorDescs,
56	                                atb::SVector<atb::TensorDesc> &outTensorDescs) {
57	        outTensorDescs.at(0) = inTensorDescs.at(0);
58	        if (param.transpose == true) {
59	            outTensorDescs.at(0).shape.dimNum = DIM3;
60	            outTensorDescs.at(0).shape.dims[0] = inTensorDescs.at(0).shape.dims[0];
61	            outTensorDescs.at(0).shape.dims[1] = inTensorDescs.at(0).shape.dims[1];
62	            outTensorDescs.at(0).shape.dims[2] = inTensorDescs.at(1).shape.dims[0] / 2;
63	        } else {
